'use strict';
const API='https://xcwuwflggiwkehzquugz.supabase.co/functions/v1/afaq-platform-api';
const GAME='https://xcwuwflggiwkehzquugz.supabase.co/functions/v1/afaq-contest-v2';
const root=document.getElementById('contestApp');
const tokenKey='afaq_access_token_v2';
const stageInfo=[
 {name:'جامبول وداروين',subtitle:'بوابة التحدي',icon:'🐱🐟',time:25,desc:'١٠ أسئلة، ٢٥ ثانية للسؤال'},
 {name:'عامر',subtitle:'تحدي المهارات',icon:'🧠⚡',time:20,desc:'١٠ أسئلة، ٢٠ ثانية للسؤال'},
 {name:'ستيف',subtitle:'سباق السرعة',icon:'🚀🎯',time:10,desc:'١٠ أسئلة، ١٠ ثوانٍ للسؤال'},
 {name:'مستر بين',subtitle:'المختبر الرياضي',icon:'🤵🧸',time:720,desc:'أسئلة مركبة، ١٢ دقيقة للمرحلة'},
 {name:'الأستاذ سعيد',subtitle:'التحدي النهائي',icon:'👨‍🏫🏆',time:600,desc:'أسئلة استدلالية، ١٠ دقائق للمرحلة'}
];
const originalCharacterArt=["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"];
for(let i=0;i<stageInfo.length;i++){stageInfo[i].icon='<img src="'+originalCharacterArt[i]+'" alt="صورة مرحلة '+(i+1)+'">';}
const S={token:sessionStorage.getItem(tokenKey)||'',user:null,grade:6,section:1,mode:'training',models:[],questions:[],question:null,index:0,answers:{},result:null,report:null,summary:null,attemptId:null,attemptNo:null,questionStarted:0,stageStarted:0,timer:null,selected:null,feedback:'',error:'',busy:false,modelEditing:'A'};
const e=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const gname=n=>({5:'الخامس',6:'السادس',7:'السابع',8:'الثامن'})[n]||n;
const staff=()=>['supervisor','supervisor_assistant','director','deputy'].includes(S.user?.role);
const officialStudent=()=>S.user?.role==='student';
const supervisor=()=>S.user?.role==='supervisor';
const named=()=>S.user?.username||'البطل';
const canOfficial=()=>officialStudent()&&S.grade===6;
const trainingTitle=()=>({student:'نموذج الطالب',demo:'نموذج الطالب',director:'نموذج الإدارة',deputy:'نموذج الإدارة',supervisor:'نموذج المشرف',supervisor_assistant:'نموذج مساعد المشرف'})[S.user?.role]||'نموذج التدريب';
const modelNames={A:'المحاولة الرسمية الأولى',B:'المحاولة الرسمية الثانية',C:'نموذج الطالب',D:'نموذج الإدارة',E:'نموذج المشرف',F:'نموذج مساعد المشرف'};
const errorWords={unauthorized:'انتهت جلسة الدخول، سجّل الدخول من المنصة أولًا.',forbidden:'حسابك غير مخوّل بهذا الخيار.',training_unavailable:'هذا النموذج غير متاح للتدريب حاليًا.',official_requires_individual_student_account:'المحاولات الرسمية تتطلب حسابًا فرديًا للصف السادس.',attempt_limit:'استُنفدت المحاولتان الرسميتان لهذه الوحدة.',previous_section_required:'يلزم إكمال الوحدة السابقة أولًا.',weekly_locked:'لم يمض أسبوع على بداية الوحدة السابقة.',official_model_not_approved:'لم يعتمد المشرف النموذج الرسمي للوحدة بعد.',question_bank_incomplete:'نموذج هذه المرحلة لم يكتمل بعد.',grade_needs_individual_accounts:'يلزم إنشاء حسابات فردية لهذا الصف قبل تشغيل المنافسة.',question_sequence_changed:'تغير ترتيب السؤال، يرجى تحديث الصفحة واستكمال المحاولة.',student_class_required:'يرجى تحديد الشعبة مع الرقم المحلي.',invalid_parts:'عدد أجزاء السؤال المركب غير صحيح.'};
async function request(endpoint,action,body={}){
 const resp=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json',...(S.token?{'Authorization':'Bearer '+S.token}:{})},body:JSON.stringify({action,...body}),cache:'no-store'});
 let data;try{data=await resp.json()}catch{throw Error('تعذر الاتصال بالخادم، تحقق من الإنترنت.')}
 if(!resp.ok||!data?.ok)throw Error(errorWords[data?.error]||('تعذر إتمام العملية: '+(data?.error||resp.status)));
 return data;
}
const api=(action,body)=>request(API,action,body);
const backend=(action,body)=>request(GAME,action,body);
const sectionName=(g,i)=>g===6?['الأعداد (١)','القياس','الهندسة','الأعداد (٢)'][i-1]:i===1?'النصف الأول من الفصل الأول':'النصف الثاني من الفصل الأول';
async function loadIdentity(){
 if(!S.token)return;
 try{
  const who=await api('me');S.user=who.user;S.grade=Number(S.user.grade||6);
  if(staff())S.grade=6;
  if(officialStudent()||S.user.role==='demo')S.report=(await backend('my_results')).report;
  else S.summary=(await backend('staff_summary')).stats;
 }catch(err){S.token='';S.user=null;sessionStorage.removeItem(tokenKey)}
}
function guest(){return `<div class="contest-lock"><div class="contest-icon">🔒</div><h2>الدخول إلى المنصة أولًا</h2><p>هذه بوابة مستقلة لنجوم آفاق الرياضيات، وتستخدم الحساب الذي سجلت الدخول به إلى المنصة. لا توجد صفحة دخول ثانية للمسابقة.</p><p>افتح منصة آفاق الرياضيات ثم سجّل الدخول من الزر العلوي، وعد إلى هذه الصفحة.</p><a class="primary" href="index.html#competition">العودة إلى منصة آفاق الرياضيات</a></div>`;}
function sections(){const count=S.grade===6?4:2;return `<div class="contest-units">${Array.from({length:count},(_,i)=>{const id=i+1,p=S.report?.parts?.[i];return `<button class="contest-unit ${S.section===id?'selected':''}" data-sec="${id}"><span class="unit-num">${id}</span><strong>${S.grade===6?'الوحدة':'القسم'} ${id} — ${e(sectionName(S.grade,id))}</strong><small>${S.grade===6?'١٠٠ درجة':'٢٥ نقطة'}</small>${p?`<small>أفضل نتيجة: ${p.best??'لا توجد'} • المتبقي: ${p.attempts_remaining} من محاولتين</small>`:''}</button>`}).join('')}</div>`;}
function roadmap(current=0,completed=0){return `<div class="stage-track">${stageInfo.map((x,i)=>`<div class="stage-node ${current===i+1?'active':''} ${completed>i?'passed':''}" aria-label="المرحلة ${i+1}"><span class="stage-emoji">${x.icon}</span><b>${i+1}. ${x.name}</b><small>${x.desc}</small><span class="stage-points">١٠ درجات</span></div>`).join('')}</div>`;}
function progressSummary(){const r=S.report;if(!r)return '';return `<div class="contest-progress"><h3>تقدمك في نجوم آفاق الرياضيات</h3><div class="contest-metrics"><div><strong>${r.total??0} / ٤٠٠</strong><small>مجموع أفضل نتائجك</small></div><div><strong>${r.completed_units??0} / ٤</strong><small>الوحدات المكتملة</small></div><div><strong>${r.attempts_remaining??8}</strong><small>المحاولات الرسمية المتبقية</small></div><div><strong>${r.points_needed??350}</strong><small>نقطة للوصول إلى ٣٥٠</small></div></div><p>${r.qualified?'🏆 حققت شرط درجات التأهل وأكملت الوحدات الأربع.':r.points_needed===0?'وصلت إلى ٣٥٠ نقطة، وأكمل الوحدات الباقية لتحقيق شرط التأهل.':'تُحتسب أفضل نتيجة من محاولتين لكل وحدة، وهدف التأهل ٣٥٠ من ٤٠٠.'}</p></div>`;}
function modeBtns(){const train=`<button class="${S.mode==='training'?'primary':'outline'}" data-mode="training">🎯 ${trainingTitle()}</button>`;const official=canOfficial()?`<button class="${S.mode==='official'?'primary':'outline'}" data-mode="official">🏆 المحاولات الرسمية</button>`:'';return `<div class="contest-modes">${train}${official}</div>`;}
function home(){const enabled=S.models.some(m=>m.grade===S.grade&&m.section===S.section&&m.model==='A'&&m.published);const ready=S.mode!=='official'||enabled;
 return `<div class="contest-home"><div class="contest-welcome"><div><span class="contest-label">مسابقة نجوم آفاق الرياضيات</span><h2>مرحبًا ${e(named())} ⭐</h2><p>الصف ${gname(S.grade)} • ${staff()?'لوحة الصلاحيات الإدارية':officialStudent()?'حساب الطالب المعتمد':'حساب تجريبي للتدريب فقط'}</p></div><button class="outline" id="logoutContest">خروج آمن</button></div>
 ${staff()?`<div class="contest-grades">${[5,6,7,8].map(g=>`<button class="${S.grade===g?'chosen':''}" data-grade="${g}">الصف ${gname(g)}</button>`).join('')}</div>`:''}
 ${sections()}${progressSummary()}<h3 class="contest-title">نموذج المسابقة والتدريب</h3>${modeBtns()}
 <p class="contest-instructions">${S.mode==='official'?'محاولتان مختلفتان للمنافسة، والنتائج الرسمية تحفظ في حسابك.':'تدريب مستقل عن درجات المنافسة ومحاولاتها، بنفس المراحل الخمس والتوقيت وطريقة احتساب النقاط.'}</p>
 ${roadmap()}<div class="contest-rules"><b>احتساب الدرجات:</b> خمس مراحل، لكل مرحلة ١٠ درجات. المراحل الثلاث الأولى ١٠ أسئلة اختيارية لكل مرحلة؛ المرحلتان الرابعة والخامسة أسئلة متعددة الأجزاء بمجموع ١٠ درجات لكل مرحلة. الدرجة الخام ٥٠ وتُضاعف إلى ١٠٠. ${S.grade===6?'تجمع أفضل نتائج الوحدات الأربع من ٤٠٠.':'للقسم الواحد ٢٥ نقطة، ويُضاعف مجموع القسمين إلى ١٠٠.'}</div>
 ${!ready?'<div class="notice">لم يعتمد المشرف المحاولة الرسمية بعد. نموذج التدريب متاح دون احتساب أي محاولة رسمية.</div>':''}${S.error?`<div class="notice" role="alert">${e(S.error)}</div>`:''}
 <div class="contest-start-wrap"><button id="begin" class="primary" ${!ready?'disabled':''}>${S.mode==='official'?'ابدأ المحاولة الرسمية':'ابدأ '+trainingTitle()}</button></div>
 ${staff()&&S.summary?`<div class="panel"><h3>ملخص نتائج الوحدات الرسمية</h3>${S.summary.map(x=>`<p>الوحدة ${x.section}: ${x.submitted} محاولة مكتملة، متوسط الدرجات ${x.average??'—'}/١٠٠</p>`).join('')}</div>`:''}${supervisor()?editPanel():''}</div>`;
}
function editPanel(){return `<div class="panel"><h3>إدارة النماذج وموافقة اللجنة — للمشرف فقط</h3><p class="muted">النماذج الرسمية مغلقة حتى تدقيق الأسئلة وإجاباتها. يحتوي النموذج الواحد على ٣٠ سؤالًا سريعًا و٨ مسائل مركبة.</p><label>اختر النموذج المطلوب مراجعته</label><select id="editModel">${Object.entries(modelNames).map(([m,n])=>`<option value="${m}" ${m===S.modelEditing?'selected':''}>${n}</option>`).join('')}</select><div class="contest-modes"><button class="outline" id="loadBank">عرض الأسئلة ومراجعتها</button></div><div id="bank"></div></div>`;}
const currentQ=()=>S.mode==='official'?S.question:S.questions[S.index];
function secondsRemaining(stage){if(stage<=3)return Math.max(0,Math.ceil((S.questionStarted+stageInfo[stage-1].time*1000-Date.now())/1000));return Math.max(0,Math.ceil((S.stageStarted+stageInfo[stage-1].time*1000-Date.now())/1000));}
function timeDisplay(n,stage){if(stage<=3)return `${n} ثانية`;return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function quiz(){const q=currentQ();if(!q)return '<div class="notice">لم يتم تحميل السؤال، حاول العودة إلى الوحدات.</div>';
 const stage=q.stage,info=stageInfo[stage-1],partNo=stage<=3?((q.ordinal-1)%10)+1:((q.ordinal-31)%4)+1;
 const remaining=secondsRemaining(stage),ratio=Math.min(100,Math.max(0,remaining/info.time*100));const answer=S.selected??S.answers[q.id];const complex=q.question_kind==='complex';
 return `<div class="contest-playing"><div class="contest-headline"><div><span>${S.mode==='official'?'🏆 محاولة رسمية':'🎯 '+trainingTitle()}</span><h2>${e(sectionName(S.grade,S.section))}</h2><small>${e(named())} • الصف ${gname(S.grade)}</small></div><div class="contest-score-badge"><strong>٥٠ ← ١٠٠</strong><small>الدرجة تُضاعف</small></div></div>${roadmap(stage,stage-1)}<div class="contest-game-area"><div class="contest-stage-banner"><div class="contest-character">${info.icon}</div><div><span class="contest-label">المرحلة ${stage} من ٥ • ١٠ درجات</span><h2>${info.name}</h2><p>${info.subtitle} — ${info.desc}</p></div><div class="contest-timer ${remaining<=5?'urgent':''}"><strong id="contestClock">${timeDisplay(remaining,stage)}</strong><small>${stage<=3?'وقت السؤال':'الوقت المتبقي للمرحلة'}</small><span class="contest-timerline"><i id="contestTimerBar" style="width:${ratio}%"></i></span></div></div>
 <div class="contest-question-meta"><span>السؤال ${partNo} من ${stage<=3?10:4}</span><span>التقدم ${S.index+1} / ٣٨</span><span>${complex?'سؤال مركب متعدد الأجزاء':'اختيار من متعدد'}</span></div>
 <div class="contest-question"><h3>${e(q.prompt)}</h3>${complex?(q.parts||[]).map((part,i)=>`<div class="contest-subpart"><h4>(${i+1}) ${e(part.text)}</h4>${part.type==='choice'?`<div class="contest-choice-grid">${(part.choices||[]).map(choice=>`<label><input type="radio" name="part${i}" value="${e(choice)}" ${Array.isArray(answer)&&String(answer[i])===String(choice)?'checked':''}><span>${e(choice)}</span></label>`).join('')}</div>`:`<input class="contest-number" inputmode="decimal" data-part="${i}" placeholder="اكتب الإجابة هنا" value="${e(Array.isArray(answer)?answer[i]??'':'')}">`}</div>`).join(''):(q.options||[]).map((option,i)=>`<button class="contest-option ${answer===i?'selected':''}" data-opt="${i}"><span class="option-letter">${'أبجد'[i]}</span>${e(option)}</button>`).join('')}<div class="contest-help" id="contestHelp">${e(S.feedback||'فكر بهدوء وأكمل إجابتك يا '+named()+'.')}</div></div>
 <div class="contest-controls"><button class="primary" id="next" ${S.busy?'disabled':''}>${S.busy?'جارٍ الحفظ...':S.index===37?'إنهاء النموذج وإظهار النتيجة':'حفظ الإجابة والمتابعة'}</button><button class="outline" id="finishEarly">${S.mode==='official'?'إنهاء المحاولة الآن':'إنهاء التدريب الآن'}</button></div><p class="muted">${S.mode==='official'?'تُحفظ إجاباتك رسميًا بعد كل سؤال، ويُتحقق من الوقت على الخادم.':'التدريب لا يُستهلك فيه عدد المحاولات الرسمية، وتظهر نتيجته في النهاية.'}</p></div></div>`;
}
function result(){const r=S.result||{},raw=Number(r.raw_score??(r.score||0)/2),score=Number(r.score??raw*2);const partPoints=S.grade===6?score:raw/2;
 return `<div class="contest-finish"><div class="contest-giant">🏆⭐🎉</div><h2>${r.training?'أكملت '+trainingTitle():'انتهت المحاولة الرسمية'}</h2><p>أحسنت يا ${e(named())}! أكملت المراحل الخمس.</p><div class="contest-metrics"><div><strong>${raw} / ٥٠</strong><small>الدرجة الأصلية</small></div><div><strong>${score} / ١٠٠</strong><small>بعد المضاعفة</small></div><div><strong>${partPoints} / ${S.grade===6?'١٠٠':'٢٥'}</strong><small>درجة هذه ${S.grade===6?'الوحدة':'القسم'}</small></div></div><p>${r.training?'هذه درجة تدريبية لا تُضاف إلى مجموع المسابقة ولا تستهلك المحاولات.':'تم حفظ نتيجتك للمنافسة الرسمية، وتُعتمد أفضل نتيجة في هذه الوحدة.'}</p>${r.training&&r.details?`<details class="contest-review"><summary>مراجعة إجابات التدريب</summary>${r.details.map((d,i)=>`<p>التحدي ${i+1}: ${d.earned}/${d.max} نقطة — ${e(d.explanation||'')}</p>`).join('')}</details>`:''}${r.expired?'<p class="notice">انتهى زمن المرحلة أو المحاولة وفق ضوابط المسابقة.</p>':''}<button class="primary" id="back">العودة إلى الوحدات والنتائج</button></div>`;
}
function render(){clearInterval(S.timer);root.innerHTML=!S.user?guest():S.result?result():currentQ()?quiz():home();bind();if(currentQ()&&!S.result)clock();}
function clock(){clearInterval(S.timer);S.timer=setInterval(()=>{const q=currentQ();if(!q){clearInterval(S.timer);return}const sec=secondsRemaining(q.stage),label=document.getElementById('contestClock'),bar=document.getElementById('contestTimerBar');if(label)label.textContent=timeDisplay(sec,q.stage);if(bar)bar.style.width=Math.min(100,Math.max(0,sec/stageInfo[q.stage-1].time*100))+'%';if(sec<=0&&!S.busy){clearInterval(S.timer);if(q.stage>=4)skipStage();else advance(true)}},250);}
async function start(){if(S.busy)return;S.busy=true;S.error='';S.feedback='';S.answers={};S.result=null;S.questions=[];S.question=null;S.index=0;S.selected=null;
 try{if(S.mode==='official'){const r=await backend('start',{grade:S.grade,section:S.section});S.attemptId=r.attempt_id;S.attemptNo=r.attempt_no;S.index=r.index;S.question=r.question;S.questionStarted=Date.parse(r.question_started_at)||Date.now();S.stageStarted=Date.parse(r.stage_started_at)||Date.now();}else{const r=await backend('training',{grade:S.grade,section:S.section});S.questions=r.questions;S.index=0;S.questionStarted=Date.now();S.stageStarted=Date.now();}}catch(err){S.error=err.message}finally{S.busy=false;render()}}
function collectResponse(){const q=currentQ();if(!q)return null;if(q.question_kind!=='complex')return S.selected??null;return (q.parts||[]).map((part,i)=>part.type==='choice'?document.querySelector(`input[name="part${i}"]:checked`)?.value??null:document.querySelector(`[data-part="${i}"]`)?.value?.trim()??null);}
async function advance(expired=false){if(S.busy)return;const q=currentQ();if(!q)return;S.busy=true;clearInterval(S.timer);const stage=q.stage;const answer=expired?null:collectResponse();
 try{if(S.mode==='official'){const r=await backend('answer',{attempt_id:S.attemptId,index:S.index,answer});await acceptOfficial(r);}else{S.answers[q.id]=answer;S.index++;S.selected=null;if(S.index>=S.questions.length)await finishTraining();else{const nextQ=S.questions[S.index];if(nextQ.stage!==stage)S.stageStarted=Date.now();S.questionStarted=Date.now();S.feedback='أكملت السؤال يا '+named()+'، تابع التحدي.';}}}catch(err){S.error=err.message;S.feedback=err.message}finally{S.busy=false;render()}}
async function skipStage(){if(S.busy)return;const q=currentQ();if(!q)return;S.busy=true;clearInterval(S.timer);
 try{if(S.mode==='official'){const r=await backend('skip_stage',{attempt_id:S.attemptId,index:S.index});await acceptOfficial(r);}else{const stage=q.stage;while(S.index<S.questions.length&&S.questions[S.index].stage===stage){S.answers[S.questions[S.index].id]=null;S.index++}if(S.index>=S.questions.length)await finishTraining();else{S.stageStarted=Date.now();S.questionStarted=Date.now();S.feedback='انتهى زمن المرحلة، ننتقل إلى التحدي التالي.'}}}catch(err){S.error=err.message;S.feedback=err.message}finally{S.busy=false;render()}}
async function acceptOfficial(r){if(r.finished){S.result={...r,training:false};S.question=null;S.questions=[];S.report=r.report||null;return}S.index=r.index;S.question=r.question;S.questionStarted=Date.parse(r.question_started_at)||Date.now();S.stageStarted=Date.parse(r.stage_started_at)||Date.now();S.selected=null;S.feedback=r.stage_changed?'تهانينا يا '+named()+'! انتهت المرحلة، وانتقل إلى التحدي التالي.':'أحسنت يا '+named()+'! تم تسجيل الإجابة.';}
async function finishTraining(){const r=await backend('check_training',{grade:S.grade,section:S.section,answers:S.answers});S.result={...r,training:true};S.questions=[];S.question=null;}
async function finishEarly(){if(S.busy)return;if(!confirm('سيُنهي هذا الاختيار المحاولة دون إمكانية العودة إلى الأسئلة المتبقية. هل تريد المتابعة؟'))return;S.busy=true;clearInterval(S.timer);try{if(S.mode==='official'){const r=await backend('submit',{attempt_id:S.attemptId});S.result={...r,training:false};S.report=r.report||null;}else await finishTraining();S.questions=[];S.question=null;S.error='';}catch(err){S.error=err.message}finally{S.busy=false;render()}}
async function refreshReport(){if(officialStudent())S.report=(await backend('my_results')).report;}
async function reviewBank(){const select=document.getElementById('editModel');if(!select)return;const model=select.value;S.modelEditing=model;
 try{const r=await backend('question_list',{grade:S.grade,section:S.section,model});const bank=document.getElementById('bank'),list=r.questions||[];bank.innerHTML=`<p class="notice">عدد أسئلة النموذج: ${list.length}/٣٨. لا تُعتمد المحاولات الرسمية إلا بعد المراجعة.</p>${list.map(q=>`<details class="contest-bank-item"><summary>${q.ordinal}. ${e(q.prompt)}</summary><form data-ordinal="${q.ordinal}"><label>نص السؤال</label><textarea rows="2" name="prompt" required>${e(q.prompt)}</textarea>${q.question_kind==='complex'?`<label>الأجزاء وإجاباتها — JSON للمشرف</label><textarea rows="8" name="parts" required>${e(JSON.stringify(q.parts,null,2))}</textarea>`:q.options.map((v,i)=>`<label>الخيار ${i+1}</label><input name="choice${i}" value="${e(v)}" required>`).join('')+`<label>رقم الخيار الصحيح (٠–٣)</label><input type="number" name="answer_index" min="0" max="3" value="${q.answer_index}">`}<label>الهدف</label><input name="objective" value="${e(q.objective)}"><label>التفسير</label><textarea rows="2" name="explanation">${e(q.explanation)}</textarea><button class="soft" type="submit">حفظ السؤال</button></form></details>`).join('')}<div class="contest-controls"><button class="primary" id="publish">اعتماد النموذج</button><button class="outline" id="unpublish">إيقاف النموذج</button></div>`;
 bank.querySelectorAll('form[data-ordinal]').forEach(form=>form.addEventListener('submit',async ev=>{ev.preventDefault();const data=new FormData(form),ordinal=Number(form.dataset.ordinal),payload={grade:S.grade,section:S.section,model,ordinal,prompt:data.get('prompt'),objective:data.get('objective'),explanation:data.get('explanation')};if(ordinal<=30){payload.options=[0,1,2,3].map(i=>data.get('choice'+i));payload.answer_index=Number(data.get('answer_index'))}else{try{payload.parts=JSON.parse(String(data.get('parts')))}catch{alert('صيغة JSON غير صحيحة.');return}}try{await backend('save_question',payload);alert('حُفظ السؤال بنجاح.')}catch(err){alert(err.message)}}));
 for(const [key,value]of [['publish',true],['unpublish',false]])bank.querySelector('#'+key).addEventListener('click',async()=>{if(value&&!confirm('هل راجعت الأسئلة وطرائق التصحيح وتريد إتاحة هذا النموذج؟'))return;try{await backend('publish_model',{grade:S.grade,section:S.section,model,published:value});S.models=(await backend('catalog')).models;alert('تم تحديث حالة النموذج.');render()}catch(err){alert(err.message)}});
 }catch(err){S.error=err.message;render()}}
function bind(){if(!S.user)return;
 document.getElementById('logoutContest')?.addEventListener('click',async()=>{clearInterval(S.timer);try{await api('logout')}catch{}sessionStorage.removeItem(tokenKey);S.token='';S.user=null;S.question=null;S.questions=[];S.result=null;render()});
 document.querySelectorAll('[data-grade]').forEach(btn=>btn.addEventListener('click',()=>{S.grade=Number(btn.dataset.grade);S.section=1;S.result=null;S.error='';render()}));
 document.querySelectorAll('[data-sec]').forEach(btn=>btn.addEventListener('click',()=>{S.section=Number(btn.dataset.sec);S.error='';S.result=null;render()}));
 document.querySelectorAll('[data-mode]').forEach(btn=>btn.addEventListener('click',()=>{S.mode=btn.dataset.mode;S.error='';render()}));
 document.getElementById('begin')?.addEventListener('click',start);
 document.querySelectorAll('[data-opt]').forEach(btn=>btn.addEventListener('click',()=>{S.selected=Number(btn.dataset.opt);document.querySelectorAll('[data-opt]').forEach(b=>b.classList.toggle('selected',b===btn))}));
 document.getElementById('next')?.addEventListener('click',()=>advance(false));
 document.getElementById('finishEarly')?.addEventListener('click',finishEarly);
 document.getElementById('back')?.addEventListener('click',async()=>{S.result=null;S.questions=[];S.question=null;S.error='';try{await refreshReport()}catch{}render()});
 document.getElementById('loadBank')?.addEventListener('click',reviewBank);
 document.getElementById('editModel')?.addEventListener('change',ev=>S.modelEditing=ev.target.value);
 
}
(async()=>{await loadIdentity();try{S.models=(await backend('catalog')).models||[]}catch(err){S.error=err.message}render()})();